using System;using System.Linq;using Mono.Cecil;
class Audit {static void Main(string[] a){var resolver=new DefaultAssemblyResolver();resolver.AddSearchDirectory(a[1]);resolver.AddSearchDirectory("vendor/bepinex-mono/BepInEx/core");using(var m=ModuleDefinition.ReadModule(a[0],new ReaderParameters{AssemblyResolver=resolver})){int misses=0;foreach(var reference in m.GetMemberReferences()){var element=reference.DeclaringType.GetElementType();var scope=element.Scope as AssemblyNameReference;if(scope==null||!(scope.Name=="mscorlib"||scope.Name.StartsWith("System")||scope.Name=="Assembly-CSharp"))continue;try{bool missing=reference is MethodReference?((MethodReference)reference).Resolve()==null:reference is FieldReference?((FieldReference)reference).Resolve()==null:false;if(missing){misses++;Console.WriteLine("MISSING "+reference.FullName);}}catch(Exception e){misses++;Console.WriteLine("UNRESOLVED "+reference.FullName+" : "+e.GetType().Name);}}Console.WriteLine("TOTAL "+misses);}}}
